/* Generated by the CSP refactor: replaces former inline on*="..." attributes.
 * Loaded after the page script so the global functions it calls already exist. */
(function () {
    'use strict';
    var handlers = {
    h1: function (event) { activateBackup(this) },
    h2: function (event) { activateBackup(this) },
    h3: function (event) { activateBackup(this) },
    h4: function (event) { openPrivacyModal() },
    h5: function (event) { openBaaModal('Executed BAA Request') },
    h6: function (event) { openAdminSignIn() },
    h7: function (event) { closeModal('activate-modal') },
    h8: function (event) { proceedToSession() },
    h9: function (event) { activateBackup(this) },
    h10: function (event) { closeModal('admin-login-modal') },
    h11: function (event) { handleAdminSignInSubmit(event) },
    h12: function (event) { closeModal('privacy-modal') },
    h13: function (event) { closeModal('privacy-modal') },
    h14: function (event) { closeModal('baa-modal') },
    h15: function (event) { handleBaaSubmit(event) },
    h16: function (event) { downloadBaaDocument() },
    h17: function (event) { closeModal('baa-modal') },
    h18: function (event) { closeModal('terms-modal') },
    h19: function (event) { closeModal('terms-modal') },
    };
    var attrToEvent = { 'data-c': 'click', 'data-s': 'submit', 'data-ch': 'change', 'data-i': 'input', 'data-kd': 'keydown', 'data-ku': 'keyup', 'data-f': 'focus', 'data-b': 'blur', 'data-mo': 'mouseover', 'data-mu': 'mouseout', 'data-md': 'mousedown', 'data-ts': 'touchstart' };
    Object.keys(attrToEvent).forEach(function (attr) {
        var nodes = document.querySelectorAll('[' + attr + ']');
        Array.prototype.forEach.call(nodes, function (el) {
            var fn = handlers[el.getAttribute(attr)];
            if (fn) el.addEventListener(attrToEvent[attr], fn);
        });
    });
})();
